const ex = $json.execution || {};
const er = ex.error || {};
const msg = [
  '🚨 *[Vanishing Files] Workflow Error*',
  '━━━━━━━━━━━━━━',
  '🔴 Node: ' + (ex.lastNodeExecuted || 'unknown'),
  '❌ Error: ' + (er.message || 'Unknown').substring(0, 250),
  '🆔 Execution: ' + (ex.id || '—'),
  '⏰ ' + new Date().toISOString()
].join('\n');
return {json: {message: msg}};

const rows = $input.all();
const valid = rows.filter(r => r.json.Episode && !isNaN(parseInt(r.json.Episode)));
const episodeNumber = valid.length + 1;
const last = valid[valid.length - 1];
const prevCliffhanger = last?.json?.Cliffhanger ||
  'A door that should not exist creaked open deep in the Mirefall woods...';

return [{
  json: {
    episodeNumber,
    prevCliffhanger,
    seriesTitle: 'The Vanishing Files',
    waPhoneNumberId: 'YOUR_WA_PHONE_NUMBER_ID',
    waRecipient: '+9779845670262',
    fbPageId: 'YOUR_FACEBOOK_PAGE_ID',
    igUserId: 'YOUR_INSTAGRAM_BUSINESS_USER_ID',
    sheetId: 'YOUR_GOOGLE_SHEET_ID',
    sheetName: 'VanishingFiles',
    audioFolderId: 'YOUR_AUDIO_FOLDER_ID',
    videoFolderId: 'YOUR_VIDEO_FOLDER_ID',
    telegramChannelId: 'YOUR_TELEGRAM_CHANNEL_ID',
    discordGuildId: 'YOUR_DISCORD_GUILD_ID',
    discordChannelId: 'YOUR_DISCORD_CHANNEL_ID',
    tiktokOpenId: 'YOUR_TIKTOK_OPEN_ID',
    scheduledAt: new Date().toISOString()
  }
}];

try {
  const r = $input.item.json;
  let raw = r?.choices?.[0]?.message?.content;
  if (!raw) return [{json: {_orValid: false, _orRaw: null}}];
  raw = raw.replace(/```json\s*/gi,'').replace(/```\s*/g,'').trim();
  const m = raw.match(/\{[\s\S]*\}/);
  if (!m) return [{json: {_orValid: false}}];
  const p = JSON.parse(m[0]);
  const ok = !!(p.episode_title && p.voiceover_text && Array.isArray(p.scene_prompts) && p.scene_prompts.length >= 4 && p.cliffhanger_text && p.social_captions);
  return [{json: {_orValid: ok, _story: ok ? p : null}}];
} catch(e) {
  return [{json: {_orValid: false, _orError: e.message}}];
}

// Try OpenRouter result first (from IF true branch), then Gemini (from IF false branch)
const cfg = $('⚙️ SET: Config & Episode Number').first().json;
const ep = cfg.episodeNumber;

let story = null;

// Check if we have a pre-validated OpenRouter story
const orItem = $input.all().find(i => i.json._orValid === true && i.json._story);
if (orItem) {
  story = orItem.json._story;
} else {
  // Try parsing Gemini response
  for (const item of $input.all()) {
    let raw = item.json?.candidates?.[0]?.content?.parts?.[0]?.text
           || item.json?.choices?.[0]?.message?.content
           || null;
    if (!raw) continue;
    raw = raw.replace(/```json\s*/gi,'').replace(/```\s*/g,'').trim();
    const m = raw.match(/\{[\s\S]*\}/);
    if (!m) continue;
    try {
      const p = JSON.parse(m[0]);
      if (p.episode_title && p.voiceover_text && p.cliffhanger_text) {
        story = p; break;
      }
    } catch(e) {}
  }
}

// Fallback defaults if all AIs fail
if (!story) {
  story = {
    episode_title: `Episode ${ep}: Into the Fog`,
    voiceover_text: `The town of Mirefall never slept. Detective Aria stood at the threshold of the abandoned mill, her flashlight cutting through decades of silence. Three people had vanished from this exact spot. And now, something watched from the dark.`,
    scene_prompts: [
      'photorealistic, cinematic, misty mountain town at dusk, abandoned streets, fog, ultra realistic, 4K, no text',
      'photorealistic, cinematic, female detective with flashlight in dark corridor, ultra realistic, 4K, no text',
      'photorealistic, cinematic, eerie old mill interior, shadows, abandoned equipment, ultra realistic, 4K, no text',
      'photorealistic, cinematic, glowing symbol on old stone wall in darkness, ultra realistic, 4K, no text'
    ],
    cliffhanger_text: 'The symbol... she had drawn this herself.',
    next_hook: 'But who led her here — and why?',
    social_captions: {
      instagram: `🌫️ Mirefall holds secrets darker than its fog. Detective Aria is about to uncover one that changes everything.\n\nEpisode ${ep} of The Vanishing Files is out NOW.\n\n#VanishingFiles #mystery #thriller #horror #suspense #series #detective #supernatural #viral #reels #fyp #scary #storytelling #shorts #episode${ep} #mystic #paranormal #crimestory #cinematic #creepy`,
      tiktok: `🔴 Episode ${ep}: She shouldn't have gone back there... #VanishingFiles #mystery #thriller #horror #fyp`,
      youtube_title: `The Vanishing Files — Episode ${ep}: Into the Fog`,
      youtube_description: `Episode ${ep} of The Vanishing Files.\n\nDetective Aria continues her investigation into Mirefall's dark secrets. Every answer leads to deeper questions.\n\n⬇️ Subscribe for daily episodes\n👍 Like if you need to know what happens next\n\n#VanishingFiles #mystery #thriller #horror #detective #supernatural`,
      facebook: `🌫️ Episode ${ep} of The Vanishing Files just dropped. Can you handle what Detective Aria found in the old mill? 👁️ #VanishingFiles #mystery`,
      twitter: `🔴 Episode ${ep} of The Vanishing Files — she went back to the mill. She shouldn't have. #VanishingFiles #mystery #thriller`,
      linkedin: `Storytelling at its core is about compelling questions. Episode ${ep} of The Vanishing Files explores how suspense drives engagement — and why viewers can't stop watching. #storytelling #content #creative`,
      telegram: `🎬 The Vanishing Files — Episode ${ep}\n\nShe went back to the mill. The symbol was waiting. 🌫️`,
      discord: `🎬 New episode of The Vanishing Files just dropped! Episode ${ep} — she went back to the mill. Things are getting dark. 👁️`
    }
  };
}

// Ensure scene_prompts has 4 entries
while (!story.scene_prompts || story.scene_prompts.length < 4) {
  story.scene_prompts = story.scene_prompts || [];
  story.scene_prompts.push(`photorealistic cinematic atmospheric mystery scene, 4K, no text, ultra realistic, episode ${ep}`);
}

// Build Pollinations image URLs (no API key needed!)
const realism = ', ultra realistic photography, Canon EOS R5, 4K RAW, cinematic, shallow depth of field, natural film grain, no CGI, no watermarks, no text';
const pollinationsUrl = (prompt, scene) => {
  const full = prompt + realism;
  return `https://image.pollinations.ai/prompt/${encodeURIComponent(full)}?width=1080&height=1920&model=flux&enhance=true&nologo=true&seed=${ep * 10 + scene}`;
};

return [{
  json: {
    ...cfg,
    ...story,
    episodeNumber: ep,
    img1_url: pollinationsUrl(story.scene_prompts[0], 1),
    img2_url: pollinationsUrl(story.scene_prompts[1], 2),
    img3_url: pollinationsUrl(story.scene_prompts[2], 3),
    img4_url: pollinationsUrl(story.scene_prompts[3], 4),
    _storySource: orItem ? 'openrouter' : (story.episode_title.includes('Into the Fog') && ep !== 1 ? 'fallback' : 'gemini')
  }
}];

const base64 = $input.item.json.audioContent || '';
return [{
  json: $input.item.json,
  binary: {
    audio: {
      data: base64,
      mimeType: 'audio/mpeg',
      fileName: `ep_${$('⚙️ SET: Config & Episode Number').first().json.episodeNumber}_voice.mp3`
    }
  }
}];

const audioFileId = $json.id || $json.fileId || '';
const audioUrl = audioFileId
  ? `https://drive.google.com/uc?export=download&id=${audioFileId}`
  : 'https://assets.mixkit.co/sfx/preview/mixkit-cinematic-mystery-suspense-592.mp3';
const story = $('🎭 CODE: Parse & Validate Story').first().json;

return [{
  json: {
    ...story,
    audioFileId,
    audioUrl,
    audioPublicUrl: audioUrl
  }
}];

const s = $input.item.json;
const ep = s.episodeNumber;
const audioUrl = s.audioUrl;
const imgs = [s.img1_url, s.img2_url, s.img3_url, s.img4_url];

const effects = ['zoomIn','zoomOut','slideLeft','slideRight'];
const filters = ['muted','muted','1970','contrast'];

const imageClips = imgs.map((url, i) => ({
  asset: {type:'image', src: url},
  start: i * 4,
  length: 4.8,
  effect: effects[i],
  filter: filters[i],
  transition: {in:'fade', out:'fade'}
}));

const headerHtml = `<div style="font-family:Georgia,serif;text-align:center;padding:20px;"><p style="font-size:22px;color:#CC1111;letter-spacing:0.12em;text-transform:uppercase;text-shadow:2px 2px 6px #000;margin:0;">THE VANISHING FILES</p><p style="font-size:15px;color:#AAAAAA;letter-spacing:0.18em;text-transform:uppercase;margin:4px 0 0 0;">EPISODE ${ep}</p></div>`;

const cliffhangerHtml = `<div style="font-family:Georgia,serif;text-align:center;padding:30px;"><p style="font-size:34px;color:#FFFFFF;font-style:italic;line-height:1.4;text-shadow:3px 3px 10px #000000;margin:0;">&ldquo;${s.cliffhanger_text}&rdquo;</p><p style="font-size:18px;color:#CC1111;letter-spacing:0.15em;text-transform:uppercase;margin:16px 0 0 0;">▶ PART ${ep + 1} SOON...</p></div>`;

const titleHtml = `<div style="font-family:Georgia,serif;text-align:center;padding:10px 40px;"><p style="font-size:24px;color:#FFFFFF;font-style:italic;text-shadow:2px 2px 6px #000;margin:0;">${s.episode_title}</p></div>`;

const payload = {
  timeline: {
    soundtrack: {
      src: audioUrl,
      effect: 'fadeIn',
      volume: 1.0
    },
    background: '#000000',
    tracks: [
      {clips: imageClips},
      {
        clips: [
          {
            asset: {type:'html', html: headerHtml, css:'body{margin:0;}', width:1080, height:160},
            start: 0, length: 4, position:'top',
            transition: {in:'fade', out:'fade'}
          },
          {
            asset: {type:'html', html: titleHtml, css:'body{margin:0;}', width:1080, height:100},
            start: 0.5, length: 3, position:'top', offset:{y:0.12},
            transition: {in:'fade', out:'fade'}
          },
          {
            asset: {type:'html', html: cliffhangerHtml, css:'body{margin:0;}', width:1000, height:280},
            start: 12.5, length: 4.5, position:'center',
            transition: {in:'fade', out:'fade'}
          }
        ]
      }
    ]
  },
  output: {
    format: 'mp4',
    size: {width:1080, height:1920},
    fps: 30,
    quality: 'high'
  }
};

return [{json: {...s, shotstackPayload: payload}}];

// Try from current render status response, or from the completed check
const statusResp = $input.item.json;
const videoUrl = statusResp?.response?.url
  || statusResp?.data?.url
  || null;

const story = $('🎭 CODE: Parse & Validate Story').first().json;
const cfg = $('⚙️ SET: Config & Episode Number').first().json;

if (!videoUrl) {
  // Fallback: try to use Creatomate or a placeholder
  return [{
    json: {
      ...cfg, ...story,
      videoUrl: null,
      videoReady: false,
      _renderError: 'Shotstack render not ready — check Creatomate fallback'
    }
  }];
}

return [{
  json: {
    ...cfg, ...story,
    videoUrl,
    videoReady: true,
    shotstackRenderId: statusResp?.response?.id || statusResp?.data?.id
  }
}];

const vidFileId = $json.id || $json.fileId || '';
const videoPublicUrl = vidFileId
  ? `https://drive.google.com/uc?export=download&id=${vidFileId}&confirm=t`
  : ($('🎬 CODE: Extract Video URL').first().json.videoUrl || '');
const videoShareUrl = vidFileId
  ? `https://drive.google.com/file/d/${vidFileId}/view?usp=sharing`
  : videoPublicUrl;

const story = $('🎭 CODE: Parse & Validate Story').first().json;
const cfg = $('⚙️ SET: Config & Episode Number').first().json;
const ep = cfg.episodeNumber;

const caps = story.social_captions || {};

return [{
  json: {
    ...cfg,
    episodeNumber: ep,
    episode_title: story.episode_title,
    voiceover_text: story.voiceover_text,
    cliffhanger_text: story.cliffhanger_text,
    next_hook: story.next_hook,
    videoFileId: vidFileId,
    videoPublicUrl,
    videoShareUrl,
    audioPublicUrl: story.audioPublicUrl || '',
    instagram_caption: caps.instagram || `Episode ${ep} of The Vanishing Files. #VanishingFiles #mystery #thriller`,
    tiktok_caption: caps.tiktok || `🔴 Ep ${ep}: She shouldn't have gone back... #VanishingFiles #mystery #fyp`,
    youtube_title: caps.youtube_title || `The Vanishing Files — Episode ${ep}`,
    youtube_description: caps.youtube_description || `Episode ${ep} of The Vanishing Files. Subscribe for daily episodes! #mystery #thriller`,
    facebook_caption: caps.facebook || `Episode ${ep} of The Vanishing Files just dropped! 👁️ #VanishingFiles`,
    twitter_caption: caps.twitter || `🔴 Episode ${ep} of The Vanishing Files — #VanishingFiles #mystery`,
    linkedin_caption: caps.linkedin || `Episode ${ep}: The art of suspense storytelling — The Vanishing Files. #storytelling #content`,
    telegram_caption: caps.telegram || `🎬 The Vanishing Files — Episode ${ep}`,
    discord_caption: caps.discord || `🎬 New episode just dropped! Episode ${ep} of The Vanishing Files 👁️`,
    _processedAt: new Date().toISOString()
  },
  binary: $input.item.binary
}];

const resp = $input.item.json || {};
const isTimeout = !resp || Object.keys(resp).length === 0 || resp._waitTimedOut === true;
const action = ((resp.query?.action) || (resp.body?.action) || '').toLowerCase().trim();
const isCancel = ['cancel','reject','no','stop'].includes(action);
const isApprove = isTimeout || !isCancel;

const base = $('🧩 CODE: Assemble Final Video Data').first();

return [{
  json: {
    ...base.json,
    _approval: {
      action: isTimeout ? 'timeout_auto_proceed' : action,
      isApproved: isApprove,
      isCancelled: isCancel,
      isTimeout
    }
  },
  binary: base.binary
}];

const r = $input.item.json;
const ok = !!(r?.id) && !r.error;
return [{json:{platform:'facebook', ok, postId: r?.id || null, error: r?.error?.message || null, postedAt: ok ? new Date().toISOString() : null}}];

const r = $input.item.json;
const ok = !!(r?.id) && !r.error;
return [{json:{platform:'instagram_reels', ok, postId: r?.id || null, error: r?.error?.message || null, postedAt: ok ? new Date().toISOString() : null}}];

const r = $input.item.json;
const ok = !!(r?.id) && !r.error;
return [{json:{platform:'youtube', ok, postId: r?.id || null, error: r?.error?.message || null, postedAt: ok ? new Date().toISOString() : null}}];

const r = $input.item.json;
const ok = !!(r?.data?.id) && !r.errors;
return [{json:{platform:'twitter', ok, postId: r?.data?.id || null, error: r?.errors?.[0]?.message || null, postedAt: ok ? new Date().toISOString() : null}}];

const r = $input.item.json;
const ok = !!(r?.id || r?.value) && !r.error;
return [{json:{platform:'linkedin', ok, postId: r?.id || r?.value || null, error: r?.message || null, postedAt: ok ? new Date().toISOString() : null}}];

const r = $input.item.json;
const ok = !!(r?.result?.message_id) && !r.error_code;
return [{json:{platform:'telegram', ok, postId: r?.result?.message_id?.toString() || null, error: r?.description || null, postedAt: ok ? new Date().toISOString() : null}}];

const r = $input.item.json;
const ok = !!(r?.id) && !r?.code;
return [{json:{platform:'discord', ok, postId: r?.id || null, error: r?.message || null, postedAt: ok ? new Date().toISOString() : null}}];

const r = $input.item.json;
const ok = r?.data?.publish_id && !r?.error?.code;
return [{json:{platform:'tiktok', ok, postId: r?.data?.publish_id || null, error: r?.error?.message || null, postedAt: ok ? new Date().toISOString() : null}}];

const items = $input.all();
const cfg = $('⚙️ SET: Config & Episode Number').first().json;
const story = $('🎭 CODE: Parse & Validate Story').first().json;
const vidData = $('🧩 CODE: Assemble Final Video Data').first().json;

const results = {};
for (const item of items) {
  const p = item.json.platform;
  if (p) results[p] = item.json.ok ? '✅' : `❌ ${item.json.error || 'failed'}`;
}

const successCount = Object.values(results).filter(v => v === '✅').length;
const totalCount = Object.keys(results).length;

const summary = [
  `🎬 *Episode ${cfg.episodeNumber} Posted!*`,
  `📖 ${story.episode_title}`,
  `✅ ${successCount}/${totalCount} platforms succeeded`,
  `🔗 ${vidData.videoShareUrl}`,
  '',
  ...Object.entries(results).map(([k,v]) => `${v} ${k}`)
].join('\n');

return [{
  json: {
    episodeNumber: cfg.episodeNumber,
    episode_title: story.episode_title,
    cliffhanger_text: story.cliffhanger_text,
    videoUrl: vidData.videoShareUrl,
    audioUrl: vidData.audioPublicUrl,
    successCount,
    totalCount,
    results,
    summaryMessage: summary,
    postedAt: new Date().toISOString(),
    ...cfg,
    ...story
  }
}];
